async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8");
  let state = initial;
  let recordIndex = 0;
  let physicalLine = 0;
  let pending = "";
  let stopped = false;
  let reachedEOF = false;

  const processLine = async (line) => {
    physicalLine++;

    if (line.trim() === "") return;

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      return;
    }

    const result = await reduce(state, value, {
      physicalLine,
      recordIndex
    });

    recordIndex++;

    state = result.state;

    if (result.done) {
      stopped = true;
    }
  };

  try {
    while (!stopped) {
      const next = await iterator.next();

      if (next.done) {
        reachedEOF = true;
        break;
      }

      const text = decoder.decode(next.value, { stream: true });
      pending += text;

      let newline;
      while (!stopped && (newline = pending.indexOf("\n")) !== -1) {
        const line = pending.slice(0, newline);
        pending = pending.slice(newline + 1);
        await processLine(line);
      }
    }

    if (!stopped) {
      pending += decoder.decode();

      if (pending.length > 0) {
        await processLine(pending);
      }
    }

    return state;
  } catch (error) {
    throw error;
  } finally {
    if (!reachedEOF) {
      const returnMethod = iterator.return;
      if (typeof returnMethod === "function") {
        try {
          await returnMethod.call(iterator);
        } catch {
          // Cleanup failures are ignored.
        }
      }
    }
  }
}
